drop function if exists public.multi_seed_131_validate_package(text, jsonb, jsonb, uuid);
create function public.multi_seed_131_validate_package(p_source_type text, p_plans jsonb, p_expected jsonb, p_athlete_id uuid)
returns void
language plpgsql
as $validate$
declare
  v_actual record;
begin
  select count(distinct p.id)::int as plans,
         count(distinct pd.id)::int as days,
         count(distinct ps.id)::int as sessions,
         count(distinct pn.id) filter (where pn.node_type = 'section')::int as section_nodes,
         count(distinct pi.id) filter (where pi.item_type = 'exercise')::int as exercise_items,
         count(distinct pi.id) filter (where pi.item_type = 'note')::int as note_items,
         count(distinct pi.id) filter (where pi.item_type = 'exercise' and pi.exercise_id is not null)::int as valid_exercise_refs,
         count(distinct p.source_ref)::int as distinct_source_refs,
         bool_and(p.status = 'draft') as all_draft,
         bool_and(p.athlete_id = p_athlete_id) as all_target_athlete
  into v_actual
  from plans.plans p
  left join plans.plan_days pd on pd.plan_id = p.id
  left join plans.plan_sessions ps on ps.plan_day_id = pd.id
  left join plans.plan_nodes pn on pn.plan_session_id = ps.id
  left join plans.plan_items pi on pi.plan_session_id = ps.id
  where p.source_type = p_source_type
    and p.source_ref in (select value->>'source_ref' from jsonb_array_elements(p_plans) value);

  if v_actual.plans <> (p_expected->>'plans')::int then raise exception 'zija-murina-131-cleaned-2026-08-18: plans expected %, found %', p_expected->>'plans', v_actual.plans; end if;
  if v_actual.days <> (p_expected->>'days')::int then raise exception 'zija-murina-131-cleaned-2026-08-18: days expected %, found %', p_expected->>'days', v_actual.days; end if;
  if v_actual.sessions <> (p_expected->>'sessions')::int then raise exception 'zija-murina-131-cleaned-2026-08-18: sessions expected %, found %', p_expected->>'sessions', v_actual.sessions; end if;
  if v_actual.section_nodes <> (p_expected->>'sectionNodes')::int then raise exception 'zija-murina-131-cleaned-2026-08-18: section nodes expected %, found %', p_expected->>'sectionNodes', v_actual.section_nodes; end if;
  if v_actual.exercise_items <> (p_expected->>'exerciseItems')::int then raise exception 'zija-murina-131-cleaned-2026-08-18: exercise items expected %, found %', p_expected->>'exerciseItems', v_actual.exercise_items; end if;
  if v_actual.note_items <> (p_expected->>'noteItems')::int then raise exception 'zija-murina-131-cleaned-2026-08-18: note items expected %, found %', p_expected->>'noteItems', v_actual.note_items; end if;
  if v_actual.valid_exercise_refs <> (p_expected->>'exerciseItems')::int then raise exception 'zija-murina-131-cleaned-2026-08-18: valid exercise refs expected %, found %', p_expected->>'exerciseItems', v_actual.valid_exercise_refs; end if;
  if v_actual.distinct_source_refs <> (p_expected->>'plans')::int then raise exception 'zija-murina-131-cleaned-2026-08-18: distinct source_refs expected %, found %', p_expected->>'plans', v_actual.distinct_source_refs; end if;
  if not coalesce(v_actual.all_draft, false) then raise exception 'zija-murina-131-cleaned-2026-08-18: not all plans are draft'; end if;
  if not coalesce(v_actual.all_target_athlete, false) then raise exception 'zija-murina-131-cleaned-2026-08-18: not all plans belong to target athlete'; end if;
end;
$validate$;

drop function if exists public.multi_seed_131_normalize_legacy_plan(uuid);
create function public.multi_seed_131_normalize_legacy_plan(p_plan_id uuid)
returns jsonb
language sql
stable
as $normalize$
  with item_rows as (
    select
      pd.date::text as date,
      nullif(btrim(pd.day_note), '') as day_note,
      nullif(ps.session_order::text, '') as session_order,
      nullif(btrim(ps.am_pm), '') as am_pm,
      nullif(btrim(ps.bta), '') as bta,
      nullif(btrim(pn.node_type), '') as node_type,
      nullif(btrim(pn.name), '') as node_name,
      nullif(pn.node_order::text, '') as node_order,
      nullif(btrim(pi.item_type), '') as item_type,
      nullif(btrim(pi.title), '') as title,
      nullif(btrim(pi.description), '') as description,
      nullif(btrim(pi.short_note), '') as short_note,
      nullif(btrim(pi.note), '') as note,
      nullif(btrim(pi.image_url), '') as image_url,
      nullif(btrim(pi.video_url), '') as video_url,
      nullif(btrim(pi.sets), '') as sets,
      nullif(btrim(pi.reps), '') as reps,
      nullif(btrim(pi.load), '') as load,
      nullif(pi.item_order::text, '') as item_order,
      nullif(pi.exercise_order::text, '') as exercise_order,
      nullif(btrim(pi.source_row_ref), '') as source_row_ref,
      nullif(btrim(pi.domain_name), '') as domain_name,
      nullif(btrim(pi.category_name), '') as category_name,
      nullif(btrim(pi.section_name), '') as section_name,
      nullif(btrim(pi.domain_color), '') as domain_color,
      nullif(btrim(pi.category_color), '') as category_color,
      nullif(btrim(pi.section_color), '') as section_color,
      nullif(btrim(pi.domain_icon_url), '') as domain_icon_url,
      nullif(btrim(pi.category_icon_url), '') as category_icon_url,
      nullif(btrim(pi.section_icon_url), '') as section_icon_url,
      nullif(btrim(pi.domain_short_note), '') as domain_short_note,
      nullif(btrim(pi.category_short_note), '') as category_short_note,
      nullif(btrim(pi.section_short_note), '') as section_short_note,
      nullif(btrim(pi.domain_note), '') as domain_note,
      nullif(btrim(pi.category_note), '') as category_note,
      nullif(btrim(pi.section_note), '') as section_note,
      nullif(pi.domain_order::text, '') as domain_order,
      nullif(pi.category_order::text, '') as category_order,
      nullif(pi.section_order::text, '') as section_order,
      case
        when pi.item_type = 'exercise' and e.exercise_code is not null then 'code'
        when pi.item_type = 'exercise' and e.slug is not null then 'slug'
        when pi.item_type = 'exercise' then 'title'
        else null
      end as exercise_key_type,
      case
        when pi.item_type = 'exercise' and e.exercise_code is not null then e.exercise_code::text
        when pi.item_type = 'exercise' and e.slug is not null then e.slug
        when pi.item_type = 'exercise' then nullif(btrim(pi.title), '')
        else null
      end as exercise_key,
      pd.block_order as sort_block_order,
      pd.block_index as sort_block_index,
      ps.session_order as sort_session_order,
      pn.node_order as sort_node_order,
      pi.item_order as sort_item_order
    from plans.plan_items pi
    join plans.plan_sessions ps on ps.id = pi.plan_session_id
    join plans.plan_days pd on pd.id = ps.plan_day_id
    left join plans.plan_nodes pn on pn.id = pi.plan_node_id
    left join library.exercises e on e.id = pi.exercise_id
    where pd.plan_id = p_plan_id
  ),
  normalized_items as (
    select jsonb_build_object(
      'date', date,
      'day_note', day_note,
      'session_order', session_order,
      'am_pm', am_pm,
      'bta', bta,
      'node_type', node_type,
      'node_name', node_name,
      'node_order', node_order,
      'item_type', item_type,
      'title', title,
      'description', description,
      'short_note', short_note,
      'note', note,
      'image_url', image_url,
      'video_url', video_url,
      'sets', sets,
      'reps', reps,
      'load', load,
      'item_order', item_order,
      'exercise_order', exercise_order,
      'source_row_ref', source_row_ref,
      'domain_name', domain_name,
      'category_name', category_name,
      'section_name', section_name,
      'domain_color', domain_color,
      'category_color', category_color,
      'section_color', section_color,
      'domain_icon_url', domain_icon_url,
      'category_icon_url', category_icon_url,
      'section_icon_url', section_icon_url,
      'domain_short_note', domain_short_note,
      'category_short_note', category_short_note,
      'section_short_note', section_short_note,
      'domain_note', domain_note,
      'category_note', category_note,
      'section_note', section_note,
      'domain_order', domain_order,
      'category_order', category_order,
      'section_order', section_order,
      'exercise_key_type', exercise_key_type,
      'exercise_key', exercise_key
    ) as item,
    date,
    sort_block_order,
    sort_block_index,
    sort_session_order,
    am_pm,
    bta,
    sort_node_order,
    sort_item_order,
    source_row_ref,
    exercise_key_type,
    exercise_key,
    title,
    description,
    note
    from item_rows
  )
  select jsonb_build_object(
    'counts', jsonb_build_object(
      'days', (select count(*)::int from plans.plan_days where plan_id = p_plan_id),
      'sessions', (select count(*)::int from plans.plan_sessions ps join plans.plan_days pd on pd.id = ps.plan_day_id where pd.plan_id = p_plan_id),
      'sections', (select count(distinct concat_ws('|', date, session_order, domain_name, category_name, section_name))::int from item_rows),
      'exerciseItems', (select count(*)::int from item_rows where item_type = 'exercise'),
      'noteItems', (select count(*)::int from item_rows where item_type = 'note'),
      'totalItems', (select count(*)::int from item_rows)
    ),
    'items', coalesce((select jsonb_agg(item order by date, sort_block_order nulls last, sort_block_index nulls last, sort_session_order nulls last, am_pm nulls last, bta nulls last, sort_node_order nulls last, sort_item_order nulls last, source_row_ref nulls last, exercise_key_type nulls last, exercise_key nulls last, title nulls last, description nulls last, note nulls last) from normalized_items), '[]'::jsonb)
  );
$normalize$;

drop function if exists public.multi_seed_131_legacy_plan_component_checksums(jsonb);
create function public.multi_seed_131_legacy_plan_component_checksums(p_normalized jsonb)
returns jsonb
language sql
immutable
as $components$
  with items as (
    select value, ord
    from jsonb_array_elements(coalesce(p_normalized->'items', '[]'::jsonb)) with ordinality as t(value, ord)
  ),
  canonical_items as (
    select jsonb_build_object(
      'date', value->'date',
      'day_note', value->'day_note',
      'session_order', value->'session_order',
      'am_pm', value->'am_pm',
      'bta', value->'bta',
      'node_type', value->'node_type',
      'node_name', value->'node_name',
      'node_order', value->'node_order',
      'item_type', value->'item_type',
      'title', value->'title',
      'description', value->'description',
      'short_note', value->'short_note',
      'note', value->'note',
      'image_url', value->'image_url',
      'video_url', value->'video_url',
      'sets', value->'sets',
      'reps', value->'reps',
      'load', value->'load',
      'item_order', value->'item_order',
      'exercise_order', value->'exercise_order',
      'source_row_ref', value->'source_row_ref',
      'domain_name', value->'domain_name',
      'category_name', value->'category_name',
      'section_name', value->'section_name',
      'domain_color', value->'domain_color',
      'category_color', value->'category_color',
      'section_color', value->'section_color',
      'domain_icon_url', value->'domain_icon_url',
      'category_icon_url', value->'category_icon_url',
      'section_icon_url', value->'section_icon_url',
      'domain_short_note', value->'domain_short_note',
      'category_short_note', value->'category_short_note',
      'section_short_note', value->'section_short_note',
      'domain_note', value->'domain_note',
      'category_note', value->'category_note',
      'section_note', value->'section_note',
      'domain_order', value->'domain_order',
      'category_order', value->'category_order',
      'section_order', value->'section_order',
      'exercise_key_type', value->'exercise_key_type',
      'exercise_key', value->'exercise_key'
    ) as item, ord
    from items
  ),
  canonical_payload as (
    select jsonb_build_object(
      'counts', jsonb_build_object(
        'days', coalesce(p_normalized#>'{counts,days}', '0'::jsonb),
        'sessions', coalesce(p_normalized#>'{counts,sessions}', '0'::jsonb),
        'sections', coalesce(p_normalized#>'{counts,sections}', '0'::jsonb),
        'exerciseItems', coalesce(p_normalized#>'{counts,exerciseItems}', '0'::jsonb),
        'noteItems', coalesce(p_normalized#>'{counts,noteItems}', '0'::jsonb),
        'totalItems', coalesce(p_normalized#>'{counts,totalItems}', '0'::jsonb)
      ),
      'items', coalesce((select jsonb_agg(item order by ord) from canonical_items), '[]'::jsonb)
    ) as payload
  ),
  component_payloads as (
    select
      coalesce((select jsonb_agg(jsonb_build_array(value->>'date', value->>'session_order', value->>'node_order', value->>'item_order', value->>'source_row_ref') order by ord) from items), '[]'::jsonb) as order_source_rows,
      coalesce((select jsonb_agg(jsonb_build_array(value->>'exercise_key_type', value->>'exercise_key') order by ord) from items), '[]'::jsonb) as exercise_keys,
      coalesce((select jsonb_agg(jsonb_build_array(value->>'sets', value->>'reps', value->>'load') order by ord) from items), '[]'::jsonb) as dose,
      coalesce((select jsonb_agg(jsonb_build_array(value->>'title', value->>'description', value->>'short_note', value->>'note') order by ord) from items), '[]'::jsonb) as text_notes,
      coalesce((select jsonb_agg(jsonb_build_array(value->>'domain_name', value->>'category_name', value->>'section_name', value->>'domain_order', value->>'category_order', value->>'section_order') order by ord) from items), '[]'::jsonb) as sections,
      coalesce((select jsonb_agg(jsonb_build_array(value->>'image_url', value->>'video_url') order by ord) from items), '[]'::jsonb) as media
  )
  select jsonb_build_object(
    'full', encode(digest(canonical_payload.payload::text, 'sha256'), 'hex'),
    'order_source_rows', encode(digest(order_source_rows::text, 'sha256'), 'hex'),
    'exercise_keys', encode(digest(exercise_keys::text, 'sha256'), 'hex'),
    'dose', encode(digest(dose::text, 'sha256'), 'hex'),
    'text_notes', encode(digest(text_notes::text, 'sha256'), 'hex'),
    'sections', encode(digest(sections::text, 'sha256'), 'hex'),
    'media', encode(digest(media::text, 'sha256'), 'hex')
  )
  from component_payloads, canonical_payload;
$components$;

