rt_note":null,"section_short_note":null,"domain_note":null,"category_note":null,"section_note":null,"domain_order":null,"category_order":"1","section_order":"1","exercise_key_type":"code","exercise_key":"1085","exercise_expected_name":"Band-Loaded Split-Stance Toe Touch"},{"plan_source_ref":"zija-murina-131-cleaned-2026-08-18:weekly:2026-08-17","date":"2026-08-20","session_order":"2","node_type":"section","node_name":"Myofascial release","node_order":"5","item_type":"exercise","title":"Brettzel - Rastezanje prednjeg dela","description":"Tokom vežbe obavezno je nomalno disanje. Povećavanjem amplitude može doći do poremećaja disanja i tonusa. To je znak da treba stati, vratiti se malo unazad, udahnuti i tokom kontrolisanog i sporog izdisanja povećati amplitudu do sledeće izazovne pozicije. Kada više nema povećavanja, zadržati tu poziciju 20s. Voditi računa da tokom cele vežbe bude normalno disanje.","short_note":null,"note":null,"image_url":"https://drive.google.com/uc?id=1es8Sgu-iktRvDL40GyMJgLin6GMdqOme","video_url":"https://drive.google.com/file/d/1NPm0vGzaTtbGE48BHedH-Y-DNUm0WsDc/view?usp=sharing","sets":"1","reps":"30+30S","load":null,"item_order":"1","exercise_order":"1","source_row_ref":"2396","domain_name":null,"category_name":"Myofascial release","section_name":"Myofascial release","domain_color":null,"category_color":"#a4c2f4","section_color":"#a4c2f4","domain_icon_url":null,"category_icon_url":"https://drive.google.com/file/d/1d4ebsgqCt-4CkTqbBV_FCV_POIuY5cJs/view?usp=drive_link","section_icon_url":"https://drive.google.com/file/d/1d4ebsgqCt-4CkTqbBV_FCV_POIuY5cJs/view?usp=drive_link","domain_short_note":null,"category_short_note":null,"section_short_note":null,"domain_note":null,"category_note":null,"section_note":null,"domain_order":null,"category_order":"5","section_order":"5","exercise_key_type":"code","exercise_key":"470","exercise_expected_name":"Brettzel - Rastezanje prednjeg dela"},{"plan_source_ref":"zija-murina-131-cleaned-2026-08-18:weekly:2026-08-17","date":"2026-08-20","session_order":"2","node_type":"section","node_name":"Myofascial release","node_order":"5","item_type":"exercise","title":"Brettzel 2.0 sa otklonom u stranu - FUL PROGRESIJA","description":"Tokom vežbe obavezno je nomalno disanje. Povećavanjem amplitude može doći do poremećaja disanja i tonusa. To je znak da treba stati, vratiti se malo unazad, udahnuti i tokom kontrolisanog i sporog izdisanja povećati amplitudu do sledeće izazovne pozicije. Kada više nema povećavanja, zadržati tu poziciju 20s. Voditi računa da tokom cele vežbe bude normalno disanje. Ruka koja je oslonac sve vreme opružena. Suprotno rame postaviti ka napred u liniji sa ramenom ruke koja je oslonac.","short_note":null,"note":null,"image_url":"https://drive.google.com/uc?id=1TIGSvRbyUpgAgMCzcN9sfbGObqgHkddB","video_url":"https://drive.google.com/file/d/18oye3Pr0y0YByMWiG0YI6ZafwiZSR_A0/view?usp=sharing","sets":"1","reps":"30+30S","load":null,"item_order":"2","exercise_order":"2","source_row_ref":"2397","domain_name":null,"category_name":"Myofascial release","section_name":"Myofascial release","domain_color":null,"category_color":"#a4c2f4","section_color":"#a4c2f4","domain_icon_url":null,"category_icon_url":"https://drive.google.com/file/d/1d4ebsgqCt-4CkTqbBV_FCV_POIuY5cJs/view?usp=drive_link","section_icon_url":"https://drive.google.com/file/d/1d4ebsgqCt-4CkTqbBV_FCV_POIuY5cJs/view?usp=drive_link","domain_short_note":null,"category_short_note":null,"section_short_note":null,"domain_note":null,"category_note":null,"section_note":null,"domain_order":null,"category_order":"5","section_order":"5","exercise_key_type":"code","exercise_key":"473","exercise_expected_name":"Brettzel 2.0 sa otklonom u stranu - FUL PROGRESIJA"},{"plan_source_ref":"zija-murina-131-cleaned-2026-08-18:weekly:2026-08-17","date":"2026-08-20","session_order":"2","node_type":"section","node_name":"Myofascial release","node_order":"5","item_type":"exercise","title":"Stride With Torso Rotation","description":"Set-Up: Stand tall with one leg on an elevated surface just above the height of the knee. The hip, knee, and ankle of the up leg are all in line and the pelvis is level. The foot on the ground is pointing straight forward. Action: Put the hands over the head, inhale and exhale while rotating towards the up leg, maintain a tall spine as well as hip, knee, and ankle alignment. Return: Rotate back to the start position.","short_note":null,"note":null,"image_url":"https://drive.google.com/uc?id=1yDf35n-wLMQ5FMBdbl7riRoOOa4U7tQn","video_url":"https://drive.google.com/file/d/1qVLZPR5rcB-uTQQSgEJi5nMHrXd_Tf-x/view?usp=sharing","sets":"1","reps":"30+30S","load":null,"item_order":"3","exercise_order":"3","source_row_ref":"2398","domain_name":null,"category_name":"Myofascial release","section_name":"Myofascial release","domain_color":null,"category_color":"#a4c2f4","section_color":"#a4c2f4","domain_icon_url":null,"category_icon_url":"https://drive.google.com/file/d/1d4ebsgqCt-4CkTqbBV_FCV_POIuY5cJs/view?usp=drive_link","section_icon_url":"https://drive.google.com/file/d/1d4ebsgqCt-4CkTqbBV_FCV_POIuY5cJs/view?usp=drive_link","domain_short_note":null,"category_short_note":null,"section_short_note":null,"domain_note":null,"category_note":null,"section_note":null,"domain_order":null,"category_order":"5","section_order":"5","exercise_key_type":"slug","exercise_key":"multi-athlete-cleaned-2026-08-18:custom:stride-with-torso-rotation:5bfdeebb72","exercise_expected_name":"Stride With Torso Rotation"},{"plan_source_ref":"zija-murina-131-cleaned-2026-08-18:weekly:2026-08-17","date":"2026-08-20","session_order":"2","node_type":"section","node_name":"Myofascial release","node_order":"5","item_type":"exercise","title":"Rastezanje p lože","description":"Tokom vežbe normalno disanje (2-3s udah, 4-6s izdah), leđa moraju biti prava u lumbalnom delu. Glava u produžetku kičme visoko postavljena. Stomak je zategnut, aktivacijom gluteusa gurati kukove na gore tokom čega će se osećati pojačano rast