  v_required_exercises jsonb := '[{"keyType":"code","key":"1004","expectedName":"Bočno zaustavljanje preko stepera sa udarcem tegom sa strane - početna pozicija tega iznad glave"},{"keyType":"code","key":"103","expectedName":"Hod sa zaključavanjem kuka - štap iznad glave"},{"keyType":"code","key":"104","expectedName":"Hod sa zaključavanjem kuka - akvavreća iznad glave"},{"keyType":"code","key":"105","expectedName":"Hod sa zaključavanjem kuka - akvalopta u jednoj ruci iznad glave"},{"keyType":"code","key":"1058","expectedName":"Squat down with both, single leg step up forefoo on plate - dumbels"},{"keyType":"code","key":"1069","expectedName":"Quadruped Band-Resisted Leg Extension"},{"keyType":"code","key":"1073","expectedName":"Standing Hip Lock with Single-Arm Band Overhead Hold"},{"keyType":"code","key":"1076","expectedName":"Standing Band-Resisted Trunk Bracing"},{"keyType":"code","key":"1077","expectedName":"Half-Kneeling Band Lift"},{"keyType":"code","key":"1079","expectedName":"Hip Lock with Single-Arm Band Overhead Press - Hip Circumduction"},{"keyType":"code","key":"1081","expectedName":"Single-Leg Step-Down Deceleration with Band Abduction-Extension"},{"keyType":"code","key":"1082","expectedName":"Landing Deceleration with Band Abduction-Extension"},{"keyType":"code","key":"1084","expectedName":"Band-Loaded Toe Touch"},{"keyType":"code","key":"1085","expectedName":"Band-Loaded Split-Stance Toe Touch"},{"keyType":"code","key":"1086","expectedName":"Supine Single-Leg Raise to Knee Extension with Band Resistance – Arms Abducted"},{"keyType":"code","key":"1088","expectedName":"Band-Assisted Leg Lowering"},{"keyType":"code","key":"109","expectedName":"Hod sa zaključavanjem kuka - sa rotacijom trupa štap na ramenima"},{"keyType":"code","key":"1090","expectedName":"Band-Assisted Cross-Over with Extended Leg"},{"keyType":"code","key":"1139","expectedName":"Asistirano spuštanje opružene noge + gluteus aktivacija + dodatna kontrakcija (odvajanje) noge"},{"keyType":"co